local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["19086b536166624d"] = { "Proprio così! Allora, la signora era tornata per un secondo tentativo con gli alveari, ma Brann non voleva saperne di quelle sciocchezze! Prima che iniziasse la mischia, lei si mise a parlare con qualcosa o qualcuno. Ancora più assurdo, cominciò a salmodiare in una lingua che nessuno di noi aveva mai sentito.", "." },
  ["19086e556f310fef"] = { "ARRRRRGH! Mi ha preso!", "." },
  ["19116dd95fa99fb5"] = { "Burp! Tesoro, era davvero buono. Non solo sai come pescare un pesce, ma sai proprio anche come cucinarlo.", "." },
  ["1921571c00f34398"] = { "È molto gentile da parte tua chiederci di cosa abbiamo bisogno, {class}. Pare però che abbiamo raccolto tutte le bende di telarunica che crediamo ci serviranno per la guerra. Posso chiederti di informarti presso alcuni degli altri raccoglitori e di dar loro una mano, se serve? Che gli antenati veglino su di te.", "." },
  ["19221c3a6ecd5774"] = { "Povero asinello. Era solo un cucciolo.", "." },
  ["1929a5862cbe7b63"] = { "Dal molo settentrionale puoi imbarcarti su una nave diretta a ⟦Rut'theran Village=Rut'theran⟧ e Darnassus. Dal molo meridionale puoi trovare un passaggio attraverso il Grande Mare fino al ⟦Menethil Harbor=Porto di Menethil⟧, a Khaz Modan. Buon viaggio!", "." },
  ["192a4c0766412679"] = { "Un esame più attento del pilone ti fa scoprire un tavolino con dei cristalli blu, gialli e verdi disposti in quella che sembra una formazione precisa.\n\nUn grande cerchio di cristalli blu è affiancato su ciascun lato da un cerchio più piccolo di cristalli gialli e da un altro di cristalli verdi.\n\nPrendi nota con cura dei colori dei cristalli, sapendo che J.D. sarebbe molto interessato a sapere cosa hai trovato.", "." },
  ["192a82d982d9c7a3"] = { "Ti serve un istruttore di Alchimia? Beh, vengo proprio da lì, sì. Troverai la signora Berryfizz a Tinker Town, dove si radunano gli gnomi.", "." },
  ["192fb6f4e9516da1"] = { "Grazie, {name}. Hai placato la fredda rabbia nel mio cuore.", "." },
  ["19308a28a0e728cb"] = { "Dov'è il tuo Medallion of Station, <piccolo/piccola>? Non puoi parlare con un duca senza una prova del tuo titolo...", "." },
  ["19311b09b6772789"] = { "%s emerge per proteggere la Fathom Stone!", "." },
  ["193a86649c8b1e30"] = { "Mi hanno invitato a visitare Dalaran per conto del ⟦Cenarion Circle=Circolo Cenariano⟧. Trovo questo posto in egual misura meraviglioso... e inquietante.\r\n\nQuanto a te, giovane {class}: se non l'hai ancora fatto, cerca ⟦Sheldras Moontree=Sheldras Quercialuna⟧ a ⟦Stormwind=Roccavento⟧. Ti insegnerà a raggiungere l'enclave del ⟦Cenarion Circle=Circolo Cenariano⟧ a ⟦Moonglade=Radaluna⟧.", "." },
  ["193cc5d66a3526ca"] = { "Buongiorno, <signore/signora>. Ti stringerei la mano, ma come vedi sono nel bel mezzo di qualcosa. Posso esserti utile?", "." },
  ["193d520777365b4d"] = { "Desidero essere il primo a darti il benvenuto, a pieno titolo, sul primo dei quattro sentieri che guideranno per sempre il tuo destino.\n\nSe hai la pietra che la terra ti ha dato, ti darò il totem che ti ha promesso.\n\nAltrimenti vattene, finché non avrai trovato la tua strada.", "." },
  ["19554cea2a9c2385"] = { "Una morte... onorevole.", "." },
  ["196235cc0620c841"] = { "Sono di nuovo fuori dall'edificio. Ora mi sposto di un altro punto di passaggio...", "." },
  ["1965faa48265406a"] = { "Lysta, fa' entrare i prigionieri.", "." },
  ["1967803746440730"] = { "Andiamocene da qui, {name}. Adesso possiamo andare!", "." },
  ["196c0cdc834842e5"] = { "Hai detto che l'avresti riavuto. Cosa significa?", "." },
  ["1976ae92a5d2f439"] = { "Cos'è stato? Hai sentito qualcosa?", "." },
  ["19944f6e3b59d28d"] = { "Addestrarti ancora va oltre le mie capacità. Parla con Telonis, nella ⟦Craftsmen's Terrace=Terrazza degli Artigiani⟧ di Darnassus. È sempre lieto di aiutare gli allievi di talento.", "." },
  ["199e5afffc441588"] = { "Pazienta, {name}. La torcia è quasi pronta.", "." },
  ["19aa5114d762d07d"] = { "Ecco il tomo mistico che cercavo.", "." },
  ["19b1c30eff995427"] = { "Non stai cercando di uccidere l'incudine con il martello, stai cercando di creare un'arma con cui uccidere i tuoi nemici. Lascia che ti mostri cosa sbagli.", "." },
  ["19b5ae5e46017240"] = { "La nostra covata più anziana è ancora lontana dalla maturità, ma con pazienza e studio siamo certi che lo stormo sarà presto pronto.", "." },
  ["19bb81582a68a4b7"] = { "Il maestro degli zeppelin", "." },
  ["19bff20b1631efa7"] = { "Non ti dispiace se mi fermo qui un momento, vero?", "." },
  ["19cbc45cc92b969f"] = { "%s manca di nuovo il bersaglio...", "." },
  ["19cff0fdfe2769e1"] = { "Pensi che ci siano pesci qui dentro?", "." },
  ["19d51d265f26bcfb"] = { "Ho troppo da fare e troppo poco tempo per farlo, {race}! Per favore, togliti di mezzo.\n\nSe sei <infetto/infetta> dalla Melma di Camola o dal Marciume del Ghoul, forse posso aiutarti.", "." },
  ["19db62d25e2af4f8"] = { "Nessuno passa e minaccia il re! Ungh, prendi questo!!", "." },
  ["19dfd8c542c80089"] = { "Un'altra gara? Due su tre!", "." },
  ["19e0823c43d0081f"] = { "Ti lucido l'armatura per un rame.", "." },
  ["19e4092173ba79b2"] = { "Come sarebbe a dire che non sai usare un'ascia?", "." },
  ["19f0c23c9f8c0f0a"] = { "Beh, i pesci non abboccano più, tanto vale che cominci a pulire ed eviscerare quello che ho pescato oggi.", "." },
  ["19f20e46c4901c4d"] = { "Impari in fretta, e non è un male. Assicurati solo di fare il lavoro come si deve, per tutto il tempo che serve. Ora temo di doverti mandare da Snarl per imparare altro. Impara ciò che può insegnarti, ma non dare ascolto alle sue parole rabbiose. Diventa così quando le figlie di Saru ridono di lui.", "." },
  ["19f36be12c3c557e"] = { "Sosteniamo gli artigiani mistici offrendo una scelta limitata di materiali arcani per mestieri. Cerchi qualcosa in particolare?", "." },
  ["19fa7828748d46e3"] = { "Di che piano si tratta?", "." },
})
